"""Build a portable, qualified balance report from native raw measurements."""
from pathlib import Path
import json,csv,statistics,collections,hashlib,html,argparse
P=argparse.ArgumentParser();P.add_argument('--root',type=Path,default=Path(__file__).resolve().parents[1]);args=P.parse_args()
R=args.root;O=R/'_shots/balance_1007';D=R/'docs';Q=D/'qa'
expected={'matrix':72,'attacks':108,'attack_controls':24,'followups':415,'stages':36,'confirmations':124,'selected_mg':9,'fresh_entry':50}
reports={k:json.loads((O/k/'report.json').read_text()) for k in expected}
for k,n in expected.items():assert len(reports[k]['runs'])==n,(k,len(reports[k]['runs']),n)
errors={k:v['errors'] for k,v in reports.items() if v['errors']}
assert not errors,errors
checks=[]
def check(v,name):checks.append({'ok':bool(v),'name':name})
attacks=reports['attacks']['runs']+reports['attack_controls']['runs']
for r in attacks:
 c=r['c'];check(r['outcome']==('hit' if c.get('positive') else 'survived'),c['id'])
 if not c.get('positive'):
  check(not r['hits'],c['id']+' no protected damage')
  if c['attack']=='rift':check(r.get('reachedSafeAt') is not None,c['id']+' reached outside pull')
  if c['attack']=='cross':check(r['attackDistance']>=60,c['id']+' crossed at least 60 pixels')
f=reports['followups']['runs'];byid={r['c']['id']:r for r in f};coop=[]
for r in f:
 id=r['c']['id']
 if id.endswith('-hp-1'):
  s=byid[id[:-1]+'0'];coop.append({'encounter':r['c']['key'],'difficulty':r['c']['diff'],'solo':s['initialHP'],'coop':r['initialHP'],'ratio':r['initialHP']/s['initialHP']})
repeat=[byid['repeat-'+str(i)] for i in range(2)]
repeat_fields=['t','outcome','shots','initialHP','health','partDamage','patterns']
repeat_equal=all(repeat[0][k]==repeat[1][k] for k in repeat_fields)
fresh=reports['fresh_entry']['runs'];fresh_repeat=[r for r in fresh if r['c']['id'].startswith('fresh-repeat-')]
fresh_equal=all(fresh_repeat[0][k]==fresh_repeat[1][k] for k in repeat_fields)
check(fresh_equal,'fresh-browser repeat agrees on combat telemetry')
for group,report in reports.items():
 for r in report['runs']:check(r.get('finite',True),group+':'+r.get('c',{}).get('id',str(r.get('stage')))+' finite motion')
for r in reports['selected_mg']['runs']:
 check(r['effectiveLoadout']['weapon']==0 and r['identity']['pilot']==r['c']['pilot'],r['c']['id']+' actual selected MG/pilot')
confirm=reports['confirmations']['runs'];native=[r for r in fresh if not r['c']['id'].startswith('fresh-repeat-')]
timings=[]
for diff in ['easy','normal','hard','furious']:
 for lv in [0,3,5]:
  a=[r for r in native if r['c']['diff']==diff and r['c']['level']==lv];wins=[r for r in a if r['outcome']=='encounter-defeated']
  timings.append({'difficulty':diff,'level':lv,'trials':len(a),'clears':len(wins),'medianClearSeconds':statistics.median(r['t'] for r in wins) if wins else None,'minSeconds':min((r['t'] for r in wins),default=None),'maxSeconds':max((r['t'] for r in wins),default=None),'sawCross':sum(any('hc-cross' in k for k in r['patterns']) for r in a)})
rows=[]
for group,report in reports.items():
 for r in report['runs']:
  if group=='stages':
   rows.append({'group':group,'id':f"stage-{r['stage']}-{r['diff']}",'difficulty':r['diff'],'pilot':'yuri','outcome':r['state'],'seconds':r['frames']/60,'deaths':r['deaths'],'validity':'bounded wave sample; legacy input controller','bossHealthFraction':None});continue
  c=r['c'];invalid=group=='followups' and c['id'].startswith('weapon-') and c.get('weapon')==8
  pool_switch=(group=='matrix' and r['outcome']=='form-transition') or c.get('form')=='sequence';bad_ace=group=='matrix' and c.get('ace')
  rows.append({'group':group,'id':c['id'],'difficulty':c['diff'],'pilot':c['pilot'],'weapon':c.get('weapon',0),'effectiveWeapon':r.get('effectiveLoadout',{}).get('weapon'),'level':c['level'],'seed':c['seed'],'coop':bool(c.get('coop')),'outcome':'phase-depleted' if c.get('form') is not None and r['outcome']=='encounter-defeated' else r['outcome'],'seconds':r['t'],'deaths':sum(h['dead'] and not h['source'].startswith('balance:') for h in r['hits']),'bossHealthFraction':None if pool_switch or bad_ace or invalid else r['hpRatio'],'moduleDamage':r.get('partDamage',0),'validity':'EXCLUDE: locked/Yuri-only orb fixture; superseded by owned-yuri-8' if invalid else 'phase health fraction excluded after pool switch' if pool_switch else 'ace HP field excluded; corrected in audit/recovery trials' if bad_ace else 'configuration only' if c['seconds']==0 else 'fresh-browser confirmation' if group=='fresh_entry' else 'isolated attack/control' if c.get('attack') else 'exploratory shared-context fixture','screenshot':f"{group}/{r['screenshot']}" if r.get('screenshot') else None})
summary={'date':'2026-10-07','runtimeCommit':'2d5b72b91c68a9c01e6fe2e24a2a6e6dbc9b229c','counts':expected,'totalMeasuredCases':sum(expected.values()),'browserErrors':errors,'checks':checks,'coopHealth':coop,'nativeMiniboss5':timings,'repeatEqual':repeat_equal,'freshRepeatEqual':fresh_equal,'repeatSeconds':{'shared':[r['t'] for r in repeat],'fresh':[r['t'] for r in fresh_repeat]},'rows':rows,'sourceHashes':{'assets/game.js':hashlib.sha256((R/'assets/game.js').read_bytes()).hexdigest(),'index.html':hashlib.sha256((R/'index.html').read_bytes()).hexdigest()},'limitations':['Controller results are not human clear rates.','Most isolated encounters skip entry cinematics; native-entry groups include 48 shared-context cases and 48 fresh-context cases plus two fresh repeats.','Baseline controller uses delayed visible geometry, not pixel recognition; most trials use primary fire and rolls, not a complete human arsenal.','Nine invalid Lightning Orb weapon fixtures are excluded; owned-yuri-8 is the supported replacement.','Rendering is sampled during accelerated simulations; 30 FPS checks concern simulation stepping, not hardware frame-rate certification.','Stage slices run at most 120 simulated seconds and are not complete campaign clears.','Complete finale attempts preserve damage/resources, but a failed attempt does not establish impossibility.','Human warning readability, enjoyment and learning remain unmeasured.',
 'The broad sweep reused a browser context and can retain player cooldown/profile state; its same-seed repeat differed by 0.283 seconds. Treat its time/ranking/recovery/co-op combat results as exploratory. The headline Stage 5 timing table uses fresh contexts.',
 'Stage 6 automatically upgrades the default primary to chaingun, including Cole. Requested weapon 0 can therefore mean effective weapon 7; nine explicit MG-selection trials confirm the actual MG separately.',
 'Encounter fixtures zero initial adaptive threat, suppress ordinary waves/allied support, and do not deliberately route to supply pickups.',
 'This pass does not exhaustively sweep all seeds, Forge variants/tiers, attack overlaps, bombs/specials, pickup routes or deliberate cheese strategies.',
 'No complete campaign or finale clear is claimed. Local-server logs contain some cancelled-request connection-abort traces; zero browser page/console/missing-response errors were recorded.']}
Q.mkdir(exist_ok=True);(Q/'balance_1007.json').write_text(json.dumps(summary,indent=2)+'\n')
cols=['group','id','difficulty','pilot','weapon','effectiveWeapon','level','seed','coop','outcome','seconds','deaths','bossHealthFraction','moduleDamage','validity','screenshot']
with (Q/'balance_1007.csv').open('w',newline='',encoding='utf-8') as out:
 w=csv.DictWriter(out,fieldnames=cols);w.writeheader();w.writerows(rows)
lines=['# BOF balance pass — October 7, 2026','','Runtime: GitHub commit `2d5b72b`. No gameplay tuning is included in this measurement pass.','',f"Completed **{sum(expected.values())} measurements**: 72 encounter baselines, 108 movement trials, 24 damage/simulation-step controls, 415 follow-ups (including 144 HP configuration checks), 36 stage slices, 124 confirmations, nine explicit MG selections and 50 fresh-browser confirmations. This is not a count of successful playthroughs. Zero recorded browser page/console/missing-file errors. Nine unsupported/locked Orb fixtures are excluded from weapon conclusions.",'','## Findings','','### Co-op health scaling is inconsistent','','The stated runtime rule is +50% HP for bosses/minibosses. Actual initialized Normal health:','','| Encounter | Solo HP | Co-op HP | Ratio |','|---|---:|---:|---:|']
for r in coop:
 if r['difficulty']=='normal':lines.append(f"| {r['encounter']} | {r['solo']:,.1f} | {r['coop']:,.1f} | {r['ratio']:.3f}× |")
lines += ['','This is a configuration finding, independent of the test controller. Rebels, ace and finale phases/forms require an explicit co-op balance decision; simply increasing the global multiplier would also change encounters already applying it.','','### Stage 5 has a steep equipment-dependent pacing curve','','These trials use a new browser context per case, restore the real offscreen entrance, and use Juggernaut/Yuri with two seeds per row. Clear times include entrance time; failures stop on the first death.','','| Difficulty | Level | Clears / trials | Median clear | Range | Saw rotating cross |','|---|---:|---:|---:|---:|---:|']
for t in timings:
 med='—' if t['medianClearSeconds'] is None else f"{t['medianClearSeconds']:.2f}s";span='—' if t['minSeconds'] is None else f"{t['minSeconds']:.2f}–{t['maxSeconds']:.2f}s"
 lines.append(f"| {t['difficulty']} | {t['level']} | {t['clears']}/{t['trials']} | {med} | {span} | {t['sawCross']}/{t['trials']} |")
lines += ['','Treat this as a pacing/recovery candidate, not a reason to multiply all enemy HP. Review the space-primary damage curve, core exposure and time available to teach the miniboss’s attack book.','','### Isolated new attacks have usable movement escapes','',f"Movement trials: {sum(not r['c'].get('positive') and r['outcome']=='survived' for r in attacks)}/{sum(not r['c'].get('positive') for r in attacks)} survived. Positive controls: {sum(r['c'].get('positive',False) and r['outcome']=='hit' for r in attacks)}/{sum(r['c'].get('positive',False) for r in attacks)} took damage. Juggernaut uses no shields, firing, rolls or specials. Reaction delays are 150/250/400 ms, with three starting positions and all four difficulties. Twelve additional movement trials use a 30 Hz simulation step.",'','The cross test measures one crossing during a dissipation interval, not an entire 360-degree attack. Rift and hook trials isolate their attack owners; they do not certify every possible overlapping hazard.','','## Methods and interpretation','','- Native Chromium runs the real game and renderer. No combat damage is faked or enemies force-killed. Online score submission is disabled in the isolated browser context.','- Encounter baselines use Yuri, Level III gear, one common seed, up to 60 seconds. The controller sees delayed geometric observations and has limited evasion logic.','- Mini5 follow-ups vary pilot, equipment and seed. Weapon screening covers all nine pilots; the close-range follow-up changes approach distance, and the Orb confirmation uses its actual Yuri unlock.','- Co-op configuration checks use actual initialized pools, followed by 48 active/mixed/missing-partner trials.','- Forty recovery trials pair ordinary starts with a recorded intentional death that invokes the real equipment-loss and respawn path.','- Updated finale trials record the nine persistent HP pools so a transition cannot masquerade as healing or a complete victory.','- The stage controller uses rolls and bombs and samples nine stages across four difficulties for up to 120 seconds. Its results must not be pooled with the newer encounter controller as one skill level.',f"- The initial shared-context repeat differed ({repeat[0]['t']:.3f}s / {repeat[1]['t']:.3f}s); fresh-stage resets retain some player cooldowns. The final fresh-browser repeats **{'matched' if fresh_equal else 'did not match'}** ({fresh_repeat[0]['t']:.3f}s / {fresh_repeat[1]['t']:.3f}s). The original timing sweep is therefore exploratory.",'','## Review priorities','','1. Resolve per-encounter co-op health scaling, including copied-form pools and module health.','2. Review the Stage 5 space-weapon damage/HP relationship at Levels 0, III and V. Preserve recovery while giving upgraded builds time to see signature attacks.','3. Review Stage 4 and Rebel attack combinations using the captured death causes. Individual escape tests pass; controller losses alone do not prove unavoidable attacks.','4. Use the paired recovery records to set a survivable path back from depleted equipment.','5. Run the human learning/readability sheet before approving global difficulty changes.','','## Evidence','','- Portable results: [JSON](qa/balance_1007.json), [CSV](qa/balance_1007.csv).','- Native screenshots and raw traces: `_shots/balance_1007/`; local dashboard `review.html`.','- Reusable harness: `_BUILD_SOURCE/balance_pass_1007.py`, `balance_lab_1007.js`, `balance_attacks_1007.js`, `balance_natural_entry_1007.js`, and `balance_stage_slices_1007.py`.','- Case vectors: `_BUILD_SOURCE/balance_cases_1007/`.','- Human session sheet: `docs/qa/balance_human_sessions_1007.csv`.','','## Practical limits','']+['- '+x for x in summary['limitations']]
recovery=[]
for key in ['s4','mini6','herald','final-host','ace']:
 for diff in ['easy','normal','hard','furious']:
  pair=[byid[f'recovery-{key}-{diff}-{i}'] for i in [0,1]]
  recovery.append({'encounter':key,'difficulty':diff,**{label:{'outcome':r['outcome'],'seconds':r['t'],'remainingHP':r['hpRatio'],'initialLoadout':r['effectiveLoadout'],'finalWeapon':r['finalWeapon'],'finalLevel':r['finalLevel'],'subsequentDeaths':sum(h['dead'] and not h['source'].startswith('balance:') for h in r['hits'])} for label,r in zip(['freshLife','afterDeath'],pair)}})
finale=[{'difficulty':r['c']['diff'],'seconds':r['t'],'outcome':r['outcome'],'lastEncounter':r['phasePools']['encounter'],'lastForm':r['phasePools']['active']} for r in f if r['c']['id'].startswith('sequence-')]
summary.update({'recoveryPairs':recovery,'finaleAttempts':finale})
(Q/'balance_1007.json').write_text(json.dumps(summary,indent=2)+'\n')
extra=['## Recovery, loadouts and endurance','','Twenty paired recovery scenarios invoke the real death/respawn path. The initial intentional death is excluded from subsequent-death counts. These are exploratory shared-context comparisons, and the controller does not deliberately route to supplies.','','| Stage 6 miniboss | Fresh Level III clear | After intentional death | HP remaining at stop |','|---|---:|---:|---:|']
for r in recovery:
 if r['encounter']=='mini6':
  x,y=r['freshLife'],r['afterDeath'];label=f"{y['seconds']:.1f}s clear" if y['outcome']=='encounter-defeated' else f"{y['seconds']:.1f}s cap"
  extra.append(f"| {r['difficulty']} | {x['seconds']:.1f}s | {label} | {y['remainingHP']:.1%} |")
extra+=['','The Normal/Hard/Furious recovery samples survived the cap but left substantial boss health. Review rebuild pickups and low-level damage before increasing those HP pools. A human pickup-route test remains necessary.','','The Normal Stage 6 co-op miniboss cleared at 34.6–35.1 seconds with two active seats; one seat against the same initialized co-op pool had 26.8% HP remaining at the 40-second cap. These are different controllers, not a controlled measure of human co-op advantage.','','The CSV preserves requested and effective weapons. Stage 6 intentionally upgrades the default primary to chaingun for all pilots, including Cole; nine explicit primary-selection trials confirm the actual MG separately. Close-range flame follow-ups change approach distance, so this screen is not a directly comparable DPS ranking.','','Four attempts starting at the final host and preserving resources ended at Continue:','','| Difficulty | Time | Last outer encounter reached |','|---|---:|---|']
for r in finale:extra.append(f"| {r['difficulty']} | {r['seconds']:.1f}s | {['Host','Ghost','Dracula / copies'][r['lastEncounter']]} |")
extra+=['','The controller did not clear the complete finale. Timed form changes are transitions, never full-boss victories. Updated per-form pools prevent a fresh pool being mistaken for healing.','','## Decisions by mode','','| Mode | First validation target |','|---|---|','| Easy | Recovery after a death with base gear and a slow pilot. |','| Normal | Intended boss duration and whether upgraded builds see signature attacks. |','| Hard | Overlapping attacks, supply routes and the cost of one mistake. |','| Furious | Full-fight and full-finale clears using the actual limited resource budget. |','','The blank human sheet covers BOSS4, MINI5, REBEL6, HARR6, MINI8 and HAMR8. Run three attempts at the same loadout per mode; distinguish first-sight from learned attempts. Record deaths, bombs, warning understanding, fairness and enjoyment. Include slow/fast pilots, stripped equipment and a mixed-experience co-op session before approving global tuning. No human results have been collected.','','Rerun instructions: [_BUILD_SOURCE/balance_cases_1007/README.md](../_BUILD_SOURCE/balance_cases_1007/README.md).','']
at=lines.index('## Review priorities');lines[at:at]=extra
(D/'BALANCE_PASS_1007.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
fields=['tester','experience','difficulty','pilot','encounter','attempt','loadout','cleared','seconds','deaths','bombs_used','warning_understood_1_5','fairness_1_5','enjoyment_1_5','cause_of_death','notes']
with (Q/'balance_human_sessions_1007.csv').open('w',newline='',encoding='utf-8') as out:
 w=csv.DictWriter(out,fieldnames=fields);w.writeheader()
 for difficulty in ['easy','normal','hard','furious']:
  for encounter in ['BOSS4','MINI5','REBEL6','HARR6','MINI8','HAMR8']:
   for attempt in [1,2,3]:w.writerow({'difficulty':difficulty,'encounter':encounter,'attempt':attempt})
cards=''.join('<tr data-diff="'+html.escape(r.get('difficulty',''))+'"><td>'+('</td><td>'.join(html.escape(str(r.get(k,''))) for k in ['group','id','outcome','deaths']))+'</td><td>'+f"{r.get('seconds',0):.2f}"+'</td><td>'+html.escape(r['validity'])+'</td><td>'+(f'<a href="{html.escape(r["screenshot"])}">pixels</a>' if r.get('screenshot') else '')+'</td></tr>' for r in rows)
page='<!doctype html><meta charset="utf-8"><title>BOF balance measurements</title><style>body{margin:30px;background:#101722;color:#e3edf8;font:15px system-ui}h1{color:#ffce76}table{border-collapse:collapse;width:100%}td,th{padding:7px;border-bottom:1px solid #344050;text-align:left}a{color:#7bc5ff}select{padding:8px;margin:10px}img{max-width:900px;width:100%}.note{max-width:1000px;color:#afc3d8}</style><h1>Bullets of Fury — balance measurements</h1><p class="note">838 measurements, including 144 HP configuration checks. Fresh-browser Stage 5 confirmations are separated from the exploratory shared-context sweep. These are test-controller observations, not human win rates. Invalid Orb fixtures and old phase-switch HP measurements are explicitly marked. Gameplay parameters remain unchanged.</p><p><a href="../../docs/BALANCE_PASS_1007.md">Findings and methods</a> · <a href="../../docs/qa/balance_1007.csv">Download table</a></p><img src="attack_contact.jpg"><p>Slow-pilot movement trials and real-damage controls, captured in native Chromium.</p><label>Difficulty <select id="filter"><option value="">All</option>'+''.join(f'<option>{d}</option>' for d in ['easy','normal','hard','furious'])+'</select></label><table><thead><tr><th>Group</th><th>Case</th><th>Outcome</th><th>Deaths</th><th>Seconds</th><th>Scope</th><th>Capture</th></tr></thead><tbody>'+cards+'</tbody></table><script>filter.onchange=()=>document.querySelectorAll("tbody tr").forEach(r=>r.hidden=!!filter.value&&r.dataset.diff!==filter.value)</script>'
(O/'review.html').write_text(page,encoding='utf-8')
print(json.dumps({'cases':len(rows),'checks':len(checks),'failedChecks':[x['name'] for x in checks if not x['ok']],'browserErrors':errors,'report':str(D/'BALANCE_PASS_1007.md')}))
